// === Uncler M Variant #5: Bioluminescent Abyss Ring & Glitch Matrix ===
// Inspired by OpenProcessing 2955184 'Unusual Globe' by u110137

const num = 180;
let counter = 0;
let mode = 1;
let ang, tang;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	ang = createVector(0, 0, 0);
	tang = createVector(HALF_PI, 0, 0);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	let bassE = (window.bassEnergy || 0.0);
	let midE = (window.midEnergy || 0.0);
	let highE = (window.highEnergy || 0.0);

	counter += (1.0 + highE * 4.0);
	tang.y = sin(frameCount * 0.018) * 1.7;
	tang.x = cos(frameCount * 0.014) * 1.5;
	ang.lerp(tang, 0.07);

	let m = 6 * TAU * cos(counter / 180) / num;
	orbitControl(0, 0, 0.5);
	rotateZ(ang.z);
	rotateY(ang.y);
	rotateX(ang.x + frameCount * 0.006);
	background(200, 95, 7);
	noFill();

	for (let i = 0; i < min(num, frameCount); i++) {
		let a = i * PI / num;
		let r = sin(a) * min(width, height) / 2.2;

		// Glitch jitter on beat & high frequency
		let glitchOffset = (highE > 0.6 && (i % 7 === 0)) ? (sin(i * 10.0 + frameCount) * 20.0 * highE) : 0;

		// Bioluminescent Cyan & Electric Indigo HSL Palette
		let hueVal = (190 + i * 0.7 + (i % 2 === 0 ? 50 : 0) + highE * 40) % 360;
		let satVal = 85 + sin(i * 0.06) * 15;
		let briVal = 80 + bEnergy * 20;
		stroke(hueVal, satVal, briVal, 80);
		strokeWeight(1.4 + (i % 5 === 0 ? 2.0 : 0) + highE * 2.0);

		push();
		switch (mode) {
			case 0:
				rotateZ(2 * (i - num / 2) * m);
				break;
			case 1:
				rotateZ((i < num / 2) * PI);
				rotateY((i - num / 2) * m);
				break;
			case 2:
				rotateZ((i < num / 2) * PI);
				rotateX((i - num / 2) * m);
				break;
		}
		translate(glitchOffset, 0, cos(a) * min(width, height) / 2.5);
		arc(0, 0, r, r, 0, PI, OPEN, 36);
		pop();
	}
}

